func (r *queryResolver) ShipmentPreviousRates(ctx context.Context, input gqlmodel.ShipmentPreviousRatesInput) (*gqlmodel.ShipmentPreviousRatesResponse, error) {
	authCtx, err := r.requirePermission(ctx, permission.ResourceShipment, permission.OpRead)
	if err != nil {
		return nil, err
	}

	originLocationID, err := pulid.MustParse(input.OriginLocationID)
	if err != nil {
		return nil, err
	}
	destinationLocationID, err := pulid.MustParse(input.DestinationLocationID)
	if err != nil {
		return nil, err
	}
	shipmentTypeID, err := pulid.MustParse(input.ShipmentTypeID)
	if err != nil {
		return nil, err
	}
	serviceTypeID, err := pulid.MustParse(input.ServiceTypeID)
	if err != nil {
		return nil, err
	}
	customerID, err := pulidPtrFromOptionalString(input.CustomerID)
	if err != nil {
		return nil, err
	}
	excludeShipmentID, err := pulidPtrFromOptionalString(input.ExcludeShipmentID)
	if err != nil {
		return nil, err
	}
	result, err := r.shipmentService.GetPreviousRates(ctx, &repositories.GetPreviousRatesRequest{
		TenantInfo:            tenantInfo(authCtx),
		OriginLocationID:      originLocationID,
		DestinationLocationID: destinationLocationID,
		ShipmentTypeID:        shipmentTypeID,
		ServiceTypeID:         serviceTypeID,
		CustomerID:            customerID,
		ExcludeShipmentID:     excludeShipmentID,
	})
	if err != nil {
		return nil, err
	}

	return previousRatesToModel(result), nil
}

func (r *shipmentResolver) OrderNumber(ctx context.Context, obj *gqlmodel.Shipment) (*string, error) {
	parent, err := r.loadShipmentOrder(ctx, obj)
	if err != nil || parent == nil {
		return nil, err
	}
	return &parent.OrderNumber, nil
}

